'use strict';const AppConstants={STORAGE_KEYS:{VISITED: 'gaming_visited',PERSONA: 'gaming_persona',XP_PROGRESS:(persona)=> `xpSystemProgress_${persona}`,READING_PROGRESS:(persona)=> `readingProgress_${persona}`},DEFAULTS:{PERSONA: 'founder',EXPIRATION_DAYS: 3},BREAKPOINTS:{MOBILE: 768,TABLET: 1024},ANIMATION:{FAST: 200,NORMAL: 300,SLOW: 500}};const Storage={getPersona(){return localStorage.getItem(AppConstants.STORAGE_KEYS.PERSONA)|| AppConstants.DEFAULTS.PERSONA;},setPersona(persona){localStorage.setItem(AppConstants.STORAGE_KEYS.PERSONA,persona);},hasVisited(){return !!localStorage.getItem(AppConstants.STORAGE_KEYS.VISITED);},markVisited(){localStorage.setItem(AppConstants.STORAGE_KEYS.VISITED,'true');},clearAll(){localStorage.removeItem(AppConstants.STORAGE_KEYS.VISITED);localStorage.removeItem(AppConstants.STORAGE_KEYS.PERSONA);},getExpirationDate(){return Date.now()+(AppConstants.DEFAULTS.EXPIRATION_DAYS*24*60*60*1000);}};const Device={isMobile(){return window.innerWidth <=AppConstants.BREAKPOINTS.MOBILE;},isTablet(){return window.innerWidth > AppConstants.BREAKPOINTS.MOBILE && window.innerWidth <=AppConstants.BREAKPOINTS.TABLET;},isDesktop(){return window.innerWidth > AppConstants.BREAKPOINTS.MOBILE;},isTouchDevice(){return 'ontouchstart' in window || navigator.maxTouchPoints > 0;}};const DOM={showLoading(elementId,message='Loading...'){const element=typeof elementId==='string' ? document.getElementById(elementId): elementId;if(element){element.innerHTML=`
                <div class="loading-state">
                    <div class="loading-spinner"></div>
                    <span>${message}</span>
                </div>
            `;}},showError(elementId,message='An error occurred'){const element=typeof elementId==='string' ? document.getElementById(elementId): elementId;if(element){element.innerHTML=`
                <div class="error-state">
                    <h3>Error</h3>
                    <p>${message}</p>
                </div>
            `;}},showEmpty(elementId,message='No content available'){const element=typeof elementId==='string' ? document.getElementById(elementId): elementId;if(element){element.innerHTML=`<p class="empty-state">${message}</p>`;}},scrollTo(target,options={}){const element=typeof target==='string' ? document.querySelector(target): target;if(element){element.scrollIntoView({behavior: 'smooth',block: 'start',...options});}}};const Router={init(config){this.config=config;this.loadFromHash();window.addEventListener('hashchange',()=> this.loadFromHash());document.querySelectorAll(`[${config.attribute}]`).forEach(link=>{link.addEventListener('click',(e)=>{e.preventDefault();const key=e.target.dataset[config.datasetKey];if(key){window.location.hash=key;}});});},loadFromHash(){const hash=window.location.hash.slice(1);if(hash && this.config.data[hash]){this.renderContent(hash);this.updateActiveState(hash);}else if(this.config.defaultHash){window.location.hash=this.config.defaultHash;}},renderContent(key){const data=this.config.data[key];if(data && this.config.render){const html=this.config.render(data);const container=document.getElementById(this.config.contentId);if(container){container.innerHTML=html;}}},updateActiveState(key){document.querySelectorAll(`[${this.config.attribute}]`).forEach(l=>{l.classList.remove('active');});const activeLink=document.querySelector(`[${this.config.attribute}="${key}"]`);if(activeLink){activeLink.classList.add('active');}}};const LazyLoader={init(){if(!('IntersectionObserver' in window)){document.querySelectorAll('img[data-src]').forEach(img=>{if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');}});return;}const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');observer.unobserve(img);}}});},{rootMargin: '50px'});document.querySelectorAll('img[data-src]').forEach(img=>{imageObserver.observe(img);});}};(function(){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{LazyLoader.init();document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){const href=this.getAttribute('href');if(href && href !=='#'){e.preventDefault();DOM.scrollTo(href);}});});if(typeof Router !=='undefined'){window.Router=Router;}});}else{LazyLoader.init();}})();if(typeof module !=='undefined' && module.exports){module.exports={AppConstants,Storage,Device,DOM,Router,LazyLoader};}window.AppConstants=AppConstants;window.Storage=Storage;window.Device=Device;window.DOM=DOM;